INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'classic', 'n./adj.', '/ˈklæsɪk/', '经典作品;典范;经典的', 'The Old Man and the Sea is a true classic of world literature.', '《老人与海》是一部真正的世界文学经典。', 'Approaching Classics', 1, 0, 'senior', 'wordlist', 'elective4', 'U4', 'classic works', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'literature', 'n.', '/ˈlɪtrətʃə(r)/', '文学;文学作品', 'Hemingway won the Nobel Prize in Literature in 1954.', '海明威于1954年获得诺贝尔文学奖。', 'Approaching Classics', 2, 0, 'senior', 'wordlist', 'elective4', 'U4', 'world literature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'novel', 'n.', '/ˈnɒvl/', '(长篇)小说', 'This famous novel tells the story of an old fisherman.', '这部著名小说讲述了一位老渔夫的故事。', 'Approaching Classics', 3, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a famous novel', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'author', 'n.', '/ˈɔːθə(r)/', '作者;作家', 'The author of the novel was an American writer.', '这部小说的作者是一位美国作家。', 'Approaching Classics', 4, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the author of the book', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'narrator', 'n.', '/nəˈreɪtə(r)/', '叙述者;讲述人', 'As a skilful narrator, Hemingway made the simple story unforgettable.', '作为高明的叙述者,海明威让这个简单的故事令人难忘。', 'Approaching Classics', 5, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a skilful narrator', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'handicap', 'n.', '/ˈhændikæp/', '不利条件;障碍;残疾', 'The old man fought on despite his physical handicap.', '尽管身体有缺陷,老人仍继续搏斗。', 'Approaching Classics', 6, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a serious handicap', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'unbearable', 'adj.', '/ʌnˈbeərəbl/', '难以忍受的;无法承受的', 'The pain in the old man''s hands was almost unbearable.', '老人手上的疼痛几乎令人无法忍受。', 'Approaching Classics', 7, 0, 'senior', 'wordlist', 'elective4', 'U4', 'unbearable pain', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intelligent', 'adj.', '/ɪnˈtelɪdʒənt/', '聪明的;有智慧的', 'He believed he was more intelligent than the shark.', '他相信自己比鲨鱼更聪明。', 'Approaching Classics', 8, 0, 'senior', 'wordlist', 'elective4', 'U4', 'an intelligent fighter', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'current', 'n.', '/ˈkʌrənt/', '水流;潮流;趋势', 'He knew what might happen when he reached the inner current.', '他知道到达内侧水流时可能会发生什么。', 'Approaching Classics', 9, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the inner current', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bleed', 'v.', '/bliːd/', '流血;出血', 'The great fish began to bleed after the shark attacked it.', '鲨鱼袭击之后,那条大鱼开始流血。', 'Approaching Classics', 10, 0, 'senior', 'wordlist', 'elective4', 'U4', 'begin to bleed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'defeat', 'v./n.', '/dɪˈfiːt/', '击败;战胜;失败', 'A man can be destroyed but not defeated, the old man said.', '老人说,一个人可以被毁灭,但不能被打败。', 'Approaching Classics', 11, 0, 'senior', 'wordlist', 'elective4', 'U4', 'accept defeat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'destroy', 'v.', '/dɪˈstrɔɪ/', '摧毁;毁灭', 'A man can be destroyed, yet he should never give up.', '一个人可以被毁灭,但绝不该放弃。', 'Approaching Classics', 12, 0, 'senior', 'wordlist', 'elective4', 'U4', 'destroy completely', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'conquer', 'v.', '/ˈkɒŋkə(r)/', '克服;战胜;征服', 'The hero slowly learns to conquer his own fear and doubt.', '主人公慢慢学会克服自己的恐惧与怀疑。', 'Approaching Classics', 13, 0, 'senior', 'wordlist', 'elective4', 'U4', 'conquer one''s fear', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'barrier', 'n.', '/ˈbæriə(r)/', '障碍;阻力;屏障', 'Language should never be a barrier to enjoying world classics.', '语言绝不应成为欣赏世界经典的障碍。', 'Approaching Classics', 14, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a language barrier', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pursuit', 'n.', '/pəˈsjuːt/', '追求;寻求;消遣', 'The pursuit of beauty and truth lies at the heart of poetry.', '对美与真理的追求是诗歌的核心。', 'Approaching Classics', 15, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the pursuit of truth', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'verse', 'n.', '/vɜːs/', '诗节;韵文;诗', 'Each verse of the poem paints a picture of spring.', '这首诗的每一节都描绘出一幅春天的画面。', 'Approaching Classics', 16, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a single verse', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'poet', 'n.', '/ˈpəʊɪt/', '诗人', 'Wordsworth was a famous English Romantic poet.', '华兹华斯是一位著名的英国浪漫主义诗人。', 'Approaching Classics', 17, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a Romantic poet', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'poetry', 'n.', '/ˈpəʊətri/', '诗歌;诗作', 'We read poetry because we belong to the human race.', '我们读诗,是因为我们属于人类。', 'Approaching Classics', 18, 0, 'senior', 'wordlist', 'elective4', 'U4', 'read poetry', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'romantic', 'adj.', '/rəʊˈmæntɪk/', '浪漫主义的;浪漫的', 'The Lake Poets were part of the Romantic movement.', '湖畔派诗人是浪漫主义运动的一部分。', 'Approaching Classics', 19, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the Romantic movement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prevail', 'v.', '/prɪˈveɪl/', '盛行;普遍存在;占上风', 'After the rain, blue sky began to prevail over the hills.', '雨过之后,蓝天开始笼罩群山。', 'Approaching Classics', 20, 0, 'senior', 'wordlist', 'elective4', 'U4', 'blue sky prevailing', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'glitter', 'v.', '/ˈɡlɪtə(r)/', '闪闪发光;闪耀', 'In the poem, the calm lake seems to glitter in the sun.', '在诗中,平静的湖面似乎在阳光下闪耀。', 'Approaching Classics', 21, 0, 'senior', 'wordlist', 'elective4', 'U4', 'glitter in the sun', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'graze', 'v.', '/ɡreɪz/', '(牛羊等)吃草', 'In Wordsworth''s poem, the cattle graze quietly in the field.', '在华兹华斯的诗里,牛群在田野中静静吃草。', 'Approaching Classics', 22, 0, 'senior', 'wordlist', 'elective4', 'U4', 'graze in the field', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cattle', 'n.', '/ˈkætl/', '牛(群)', 'The cattle in the poem feed peacefully like one animal.', '诗中的牛群像一头牲畜般安详地进食。', 'Approaching Classics', 23, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a herd of cattle', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bare', 'adj.', '/beə(r)/', '光秃秃的;裸露的;空的', 'Snow still lingers on the top of the bare hill.', '光秃秃的山顶上仍残留着积雪。', 'Approaching Classics', 24, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the bare hill', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'joy', 'n.', '/dʒɔɪ/', '欢乐;喜悦', 'There is joy in the mountains when spring returns.', '春天回来时,群山之中充满欢乐。', 'Approaching Classics', 25, 0, 'senior', 'wordlist', 'elective4', 'U4', 'joy in the mountains', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'amid', 'prep.', '/əˈmɪd/', '在……之中;在……过程中', 'Amid the noise of the city, poetry reminds us why we live.', '在城市的喧嚣中,诗歌提醒我们为何而活。', 'Approaching Classics', 26, 0, 'senior', 'wordlist', 'elective4', 'U4', 'amid the noise', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'faithless', 'adj.', '/ˈfeɪθləs/', '不忠诚的;不可信赖的', 'Whitman asks what good there is amid the faithless crowds.', '惠特曼追问,在不忠的人群中又有什么意义。', 'Approaching Classics', 27, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the faithless crowds', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'contribute', 'v.', '/kənˈtrɪbjuːt/', '贡献;增添;促成', 'Each of us may contribute a verse to the play of life.', '我们每个人都能为生命这出戏添上一句诗。', 'Approaching Classics', 28, 0, 'senior', 'wordlist', 'elective4', 'U4', 'contribute a verse', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'inspiration', 'n.', '/ˌɪnspəˈreɪʃn/', '灵感;鼓舞;启发', 'The old man drew inspiration from the great baseball player.', '老人从那位伟大的棒球选手身上汲取灵感。', 'Approaching Classics', 29, 0, 'senior', 'wordlist', 'elective4', 'U4', 'draw inspiration from', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'determination', 'n.', '/dɪˌtɜːmɪˈneɪʃn/', '决心;坚定', 'The fisherman faced the sharks with quiet determination.', '渔夫以沉静的决心面对群鲨。', 'Approaching Classics', 30, 0, 'senior', 'wordlist', 'elective4', 'U4', 'with quiet determination', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dignity', 'n.', '/ˈdɪɡnəti/', '尊严;庄重', 'The old man fought for his pride and dignity to the end.', '老人为自己的骄傲与尊严战斗到底。', 'Approaching Classics', 31, 0, 'senior', 'wordlist', 'elective4', 'U4', 'fight for one''s dignity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'decency', 'n.', '/ˈdiːsnsi/', '正派;体面;得体', 'Hemingway praised the old man''s decency and courage.', '海明威赞美老人的正派与勇气。', 'Approaching Classics', 32, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a sense of decency', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pity', 'n.', '/ˈpɪti/', '怜悯;同情;憾事', 'This time Hemingway wrote about pity and human love.', '这一次,海明威写的是怜悯与人间的爱。', 'Approaching Classics', 33, 0, 'senior', 'wordlist', 'elective4', 'U4', 'feel pity for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sympathy', 'n.', '/ˈsɪmpəθi/', '同情;同情心', 'We feel deep sympathy for the lonely old fisherman.', '我们对孤独的老渔夫深感同情。', 'Approaching Classics', 34, 0, 'senior', 'wordlist', 'elective4', 'U4', 'feel sympathy for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'simplicity', 'n.', '/sɪmˈplɪsəti/', '简朴;简单;质朴', 'The beauty of Hemingway''s style lies in its simplicity.', '海明威文风之美在于它的质朴。', 'Approaching Classics', 35, 0, 'senior', 'wordlist', 'elective4', 'U4', 'beauty and simplicity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'authority', 'n.', '/ɔːˈθɒrəti/', '权威;权力;当局', 'A classic is often a work of high authority in its field.', '经典往往是某一领域里极具权威的作品。', 'Approaching Classics', 36, 0, 'senior', 'wordlist', 'elective4', 'U4', 'of high authority', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'appreciation', 'n.', '/əˌpriːʃiˈeɪʃn/', '欣赏;鉴赏;感激', 'Reading classics deepens our appreciation of beauty.', '阅读经典加深了我们对美的鉴赏。', 'Approaching Classics', 37, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the appreciation of beauty', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'enduring', 'adj.', '/ɪnˈdjʊərɪŋ/', '持久的;不朽的', 'Great literature deals with enduring, timeless truths.', '伟大的文学探讨的是永恒不朽的真理。', 'Approaching Classics', 38, 0, 'senior', 'wordlist', 'elective4', 'U4', 'enduring truths', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'monologue', 'n.', '/ˈmɒnəlɒɡ/', '独白;长篇大论', '''All the world''s a stage'' is Shakespeare''s famous monologue.', '“全世界是一个舞台”是莎士比亚著名的独白。', 'Approaching Classics', 39, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a famous monologue', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'playwright', 'n.', '/ˈpleɪraɪt/', '剧作家', 'Shakespeare is seen as the greatest playwright of all time.', '莎士比亚被视为有史以来最伟大的剧作家。', 'Approaching Classics', 40, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a great playwright', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sonnet', 'n.', '/ˈsɒnɪt/', '十四行诗', 'Shakespeare wrote more than one hundred and fifty sonnets.', '莎士比亚写了一百五十多首十四行诗。', 'Approaching Classics', 41, 0, 'senior', 'wordlist', 'elective4', 'U4', 'write a sonnet', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'curtain', 'n.', '/ˈkɜːtn/', '(舞台)幕布;窗帘', 'When the curtain rose, the actors began the play.', '幕布升起时,演员们开始了演出。', 'Approaching Classics', 42, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the stage curtain', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'auditorium', 'n.', '/ˌɔːdɪˈtɔːriəm/', '礼堂;观众席', 'The whole auditorium fell silent as the poem began.', '诗朗诵开始时,整个礼堂安静了下来。', 'Approaching Classics', 43, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a quiet auditorium', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'appearance', 'n.', '/əˈpɪərəns/', '露面;演出;外表', 'The young actor made his first appearance on the stage.', '这位年轻演员首次登台演出。', 'Approaching Classics', 44, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a stage appearance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lecture', 'n.', '/ˈlektʃə(r)/', '讲座;讲课;演讲', 'The students wished their teacher would give a lecture on poems.', '学生们希望老师能给他们开一堂关于诗歌的讲座。', 'Approaching Classics', 45, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a lecture on poems', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intend', 'v.', '/ɪnˈtend/', '打算;计划;想要', 'The poet did not intend his words to be forgotten.', '诗人并不想让自己的诗句被遗忘。', 'Approaching Classics', 46, 0, 'senior', 'wordlist', 'elective4', 'U4', 'intend to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intently', 'adv.', '/ɪnˈtentli/', '专注地;热切地', 'The class listened intently as the teacher read the verse.', '老师朗读诗句时,全班专注地听着。', 'Approaching Classics', 47, 0, 'senior', 'wordlist', 'elective4', 'U4', 'listen intently', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'deliver', 'v.', '/dɪˈlɪvə(r)/', '发表;发出;递送', 'She will deliver a speech about Chinese classics on Reading Day.', '她将在读书日发表一篇关于中国经典的演讲。', 'Approaching Classics', 48, 0, 'senior', 'wordlist', 'elective4', 'U4', 'deliver a speech', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u4.01', '①wish + 一般过去时(对现在的遗憾/此刻的非真实愿望)', 'A2', 12, '上外版选择性必修第四册 U4 — 对现在状况的遗憾或此刻达不到的愿望,wish 后从句用一般过去时(be 多用 were);句中常有 now / so I could… 等现在线索。陈述语气的现在式/将来式/现在完成式都不能跟在 wish 之后,故只有过去式成立。', 1, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u4.02', '②wish + 过去完成时(对过去的遗憾)', 'A2', 12, '上外版选择性必修第四册 U4 — 对过去已发生或未发生之事的遗憾,wish 后从句用过去完成时(had done / hadn''t done);句中常有 last week / yesterday / before… 等过去时间线索,使一般过去时(表现在非真实)不成立,只有过去完成时正确。', 2, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se4u4.03', '③wish + would/could · if only 各式', 'A2', 12, '上外版选择性必修第四册 U4 — wish + would do 表对将来变化的期盼或对当下行为的不满;wish + could do 表此刻欠缺的能力或将来的可能;if only 可替换 I wish,后接过去时(对现在)、过去完成时(对过去)或 could do。干扰项为陈述语气的 will/can/现在式/进行式,均不能跟在 wish/if only 之后。', 3, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"How she wishes she ____ Spanish, so she could read Neruda''s poems in the original now!"', 'knew', 'knows', 'will know', 'has known', 'A', '对现在的非真实愿望(此刻并不懂西班牙语),wish 后用一般过去时;现在式/将来式/现在完成式都不能跟在 wish 之后。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ the deeper meaning of this classic poem."', 'understand', 'understood', 'will understand', 'have understood', 'B', '对当下理解力的遗憾,用一般过去时表此刻的非真实状况。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"He wishes he ____ enough free time to read all the great novels."', 'has', 'will have', 'had', 'is having', 'C', '现在并没有足够时间,wish 后用一般过去时表非真实现状。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish this ancient text ____ a little easier to read."', 'is', 'will be', 'has been', 'were', 'D', '对现在状况的愿望,be 动词在虚拟里多用 were。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"She wishes she ____ near a big library full of classics."', 'lived', 'lives', 'will live', 'is living', 'A', '现实是她并不住在附近,wish 后用一般过去时表非真实现状。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ a complete set of Shakespeare''s plays."', 'own', 'owned', 'will own', 'have owned', 'B', '对现在没有的东西表愿望,用一般过去时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ Italian, so I could read Dante in the original."', 'speak', 'will speak', 'spoke', 'have spoken', 'C', 'so I could… 表明是当下的非真实愿望,用一般过去时 spoke。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"He wishes he ____ every line of that famous monologue by heart."', 'remembers', 'will remember', 'has remembered', 'remembered', 'D', '对现在记不住的遗憾,用一般过去时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ more about the Lake Poets and their lives."', 'knew', 'know', 'will know', 'have known', 'A', '对现在了解不足的遗憾,用一般过去时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"She wishes she ____ as beautifully as Su Shi once did."', 'writes', 'wrote', 'will write', 'has written', 'B', '对当下能力的非真实愿望,用一般过去时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ the patience to enjoy such long classics."', 'have', 'will have', 'had', 'am having', 'C', '现在缺乏耐心,wish 后用一般过去时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ as wise as the old fisherman in the story."', 'am', 'will be', 'have been', 'were', 'D', '对现在的非真实愿望,be 用 were。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ poetry as much as my literature teacher does."', 'enjoyed', 'enjoy', 'will enjoy', 'have enjoyed', 'A', '对当下感受的非真实愿望,用一般过去时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"She wishes she ____ why this old novel is called a classic."', 'understands', 'understood', 'will understand', 'has understood', 'B', '对现在不明白的遗憾,用一般过去时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"We wish our teacher ____ a class on classic Chinese poems."', 'teaches', 'will teach', 'taught', 'is teaching', 'C', '对现状(老师并不教这门课)的非真实愿望,用一般过去时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ in the age of the great Romantic poets."', 'live', 'will live', 'have lived', 'lived', 'D', '与现实相反的愿望,用一般过去时表非真实。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish everyone in my class ____ about books the way you do."', 'spoke', 'speaks', 'will speak', 'is speaking', 'A', '对现状的非真实愿望,用一般过去时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish my little brother ____ reading classics as much as I do."', 'likes', 'liked', 'will like', 'has liked', 'B', '现实是他并不喜欢,wish 后用一般过去时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"He wishes he ____ an old first edition of that famous novel."', 'owns', 'will own', 'owned', 'is owning', 'C', '对现在没有之物的愿望,用一般过去时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.01'), '"I wish I ____ as moved by poetry as my best friend is."', 'feel', 'will feel', 'have felt', 'felt', 'D', '对当下感受的非真实愿望,用一般过去时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ that classic novel before the exam last week."', 'had read', 'read', 'have read', 'will read', 'A', 'last week 表过去,对过去未做之事的遗憾,wish 后用过去完成时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"He wishes he ____ reading War and Peace before yesterday''s literature quiz."', 'finished', 'had finished', 'has finished', 'will finish', 'B', 'yesterday 锁定过去,对过去的遗憾用过去完成时 had finished。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ up so late reading Gone with the Wind last night."', 'didn''t stay', 'haven''t stayed', 'hadn''t stayed', 'won''t stay', 'C', 'last night 表过去,对昨晚行为的后悔用过去完成时的否定式。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"She wishes she ____ to the poetry recital yesterday evening."', 'went', 'has gone', 'will go', 'had gone', 'D', 'yesterday evening 表过去,对过去未去的遗憾用过去完成时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ those cruel words to my best friend an hour ago."', 'hadn''t said', 'didn''t say', 'haven''t said', 'won''t say', 'A', 'an hour ago 表过去,对说过的话后悔,用过去完成时的否定式。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"He wishes he ____ the great DiMaggio play before that star retired."', 'saw', 'had seen', 'has seen', 'will see', 'B', 'before that star retired 指过去,对过去错过之事的遗憾用过去完成时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ more attention during yesterday''s lecture on Shakespeare."', 'paid', 'have paid', 'had paid', 'will pay', 'C', 'yesterday 表过去,对过去未做好的遗憾用过去完成时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"They wish they ____ the old fisherman''s advice earlier in the story."', 'followed', 'have followed', 'will follow', 'had followed', 'D', 'earlier 指此前,对过去未做之事的遗憾用过去完成时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ the poem by heart for last week''s competition."', 'had learned', 'learned', 'have learned', 'will learn', 'A', 'last week 表过去,对过去准备不足的遗憾用过去完成时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"She wishes she ____ the real ending before a friend spoilt it for her."', 'knew', 'had known', 'has known', 'will know', 'B', 'before a friend spoilt it 指过去,对过去的遗憾用过去完成时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ that rare copy when it was still on sale last month."', 'bought', 'have bought', 'had bought', 'will buy', 'C', 'last month 表过去,对过去未买的遗憾用过去完成时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"He wishes he ____ the chance to meet the famous author years ago."', 'took', 'has taken', 'will take', 'had taken', 'D', 'years ago 表过去,对过去错过机会的遗憾用过去完成时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ harder when I first began learning calligraphy."', 'had tried', 'tried', 'have tried', 'will try', 'A', 'when I first began 指过去起点,对过去的遗憾用过去完成时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"We wish we ____ the museum of classics during our trip last summer."', 'visited', 'had visited', 'have visited', 'will visit', 'B', 'last summer 表过去,对过去未做之事的遗憾用过去完成时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ my essay on Su Shi before the deadline passed."', 'wrote', 'have written', 'had written', 'will write', 'C', 'before the deadline passed 指过去,对过去未完成的遗憾用过去完成时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"She wishes she ____ a shorter classic for her first book report last term."', 'chose', 'has chosen', 'will choose', 'had chosen', 'D', 'last term 表过去,对过去选择的遗憾用过去完成时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ the teacher when she explained that difficult verse yesterday."', 'had asked', 'asked', 'have asked', 'will ask', 'A', 'yesterday 表过去,对过去未问的遗憾用过去完成时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"He wishes he ____ the poetry club in his very first year at school."', 'joined', 'had joined', 'has joined', 'will join', 'B', 'first year(已过去)指过去,对过去未做的遗憾用过去完成时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"I wish I ____ that line correctly during last night''s recitation contest."', 'recited', 'have recited', 'had recited', 'will recite', 'C', 'last night 表过去,对过去表现的遗憾用过去完成时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.02'), '"They wish they ____ the play when it was first performed long ago."', 'watched', 'have watched', 'will watch', 'had watched', 'D', 'when it was first performed long ago 指过去,对过去错过的遗憾用过去完成时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish those noisy students ____ stop talking during the poetry reading."', 'would stop', 'will stop', 'stop', 'are stopping', 'A', '对他人当下行为的不满、盼其改变,wish 后用 would do;陈述语气的 will/现在式/进行式都不能跟在 wish 之后。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish my brother ____ read more classics instead of only comics."', 'will read', 'would read', 'reads', 'is reading', 'B', '盼对方将来改变习惯,用 wish + would do。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish our teacher ____ give us a lecture on Shakespeare one day."', 'will give', 'gives', 'would give', 'is giving', 'C', '对将来的期盼,用 wish + would do。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish people ____ stop spoiling the endings of famous novels."', 'will stop', 'stop', 'have stopped', 'would stop', 'D', '盼他人行为改变,用 wish + would do。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish I ____ write poetry as beautifully as Wordsworth."', 'could write', 'can write', 'will write', 'am writing', 'A', '表此刻欠缺的能力,用 wish + could do;陈述语气的 can/will/进行式都不能跟在 wish 之后。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish I ____ recite the whole monologue without a single mistake."', 'can recite', 'could recite', 'will recite', 'is reciting', 'B', '表当下做不到的能力,用 wish + could do。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish I ____ meet my favourite novelist in person some day."', 'can meet', 'will meet', 'could meet', 'am meeting', 'C', '表难以实现的将来愿望,用 wish + could do。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish I ____ understand classical Chinese poems more easily."', 'can understand', 'will understand', 'is understanding', 'could understand', 'D', '表当下欠缺的能力,用 wish + could do。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ play the guzheng like the girl in the contest!"', 'could play', 'can play', 'will play', 'am playing', 'A', 'if only 表强烈愿望、能力当下达不到,用 could do。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ travel back to the age of the great poets!"', 'can travel', 'could travel', 'will travel', 'am travelling', 'B', 'if only 表不可能实现的愿望,用 could do。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only this difficult classic ____ a little shorter!"', 'is', 'will be', 'were', 'has been', 'C', 'if only 对现在状况的非真实愿望,be 用 were。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ more free time to read for pleasure!"', 'have', 'will have', 'am having', 'had', 'D', 'if only 对现在的非真实愿望,用一般过去时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only my handwriting ____ as neat as a calligrapher''s!"', 'were', 'is', 'will be', 'has been', 'A', 'if only 对现在状况的非真实愿望,be 用 were。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ such a cruel thing to her yesterday!"', 'didn''t say', 'hadn''t said', 'don''t say', 'won''t say', 'B', 'yesterday 表过去,if only 对过去的后悔用过去完成时的否定式。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ the whole novel before watching the film last night!"', 'read', 'have read', 'had read', 'will read', 'C', 'last night 表过去,if only 对过去的遗憾用过去完成时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ to the recital before it ended yesterday evening!"', 'went', 'have gone', 'will go', 'had gone', 'D', 'yesterday evening 表过去,if only 对过去的遗憾用过去完成时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"If only I ____ harder for last week''s literature exam!"', 'had studied', 'studied', 'have studied', 'will study', 'A', 'last week 表过去,if only 对过去的遗憾用过去完成时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish my old computer ____ open these poetry files a bit faster."', 'will open', 'would open', 'opens', 'is opening', 'B', '盼其行为改变,用 wish + would do。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish I ____ remember every line of my favourite sonnet."', 'can remember', 'will remember', 'could remember', 'am remembering', 'C', '表当下达不到的能力,用 wish + could do。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective4' AND unit='U4' AND code='se4u4.03'), '"I wish the library ____ stay open later during exam week."', 'will stay', 'stays', 'is staying', 'would stay', 'D', '盼将来情况改变,用 wish + would do。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Old Man and the Sea', 'Ernest Hemingway''s The Old Man and the Sea tells the story of Santiago, an old fisherman who has caught nothing for many days. At last he hooks a giant fish, far bigger than his small boat. For three days the old man holds on, fighting the great fish with all his strength until he finally wins. On the way home, however, sharks smell the blood and attack again and again. One by one they tear away the flesh, and the old man fights back with a harpoon, a knife and even an oar. By the time he reaches the shore, only the bones of the fish are left. Yet Santiago is not broken. A man can be destroyed but not defeated, he believes. Though he loses the fish, he keeps his courage and his pride. This simple story has moved readers all over the world and helped make Hemingway one of the most respected writers of his time.', '小说·《老人与海》的故事', 158, '[{"q":"How long does the old man struggle before he finally catches the great fish?","answer":"A","options":["For three days and nights.","For only a few minutes.","For a whole month.","He never manages to catch it."],"explanation":"原文 ''For three days the old man holds on… until he finally wins'' 的转述。"},{"q":"What is left of the fish by the time he gets home?","answer":"B","options":["The whole fish, undamaged.","Almost nothing but its bones.","Half of the fresh meat.","Only its head."],"explanation":"原文 ''only the bones of the fish are left'' 的转述。"},{"q":"What does the story mainly show about Santiago?","answer":"A","options":["He keeps his courage even in defeat.","He gives up as soon as life is hard.","He cares only about money.","He is too afraid to go to sea."],"explanation":"末段 ''keeps his courage and his pride… not defeated'' 的概括。"}]'::jsonb, '[{"word":"fisherman","cn":"渔夫"},{"word":"shark","cn":"鲨鱼"},{"word":"defeated","cn":"被打败的"}]'::jsonb, 2, 'elective4', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Hemingway''s Iceberg Style', 'Hemingway is famous for his brief and simple writing style. He once said that good writing is like an iceberg: only a small part shows above the water, while most of the meaning lies hidden beneath. In The Old Man and the Sea, his sentences are short and his words are plain, yet they carry deep feeling. He rarely tells the reader what to think. Instead, he describes simple actions, the old man''s hands, the sea and the fish, and lets the reader feel the emotion behind them. This quiet style makes the characters seem real and strong. Because so much is left unsaid, every single word matters, and readers must use their own imagination to fill in the rest. Many later writers have tried to copy this clear and powerful way of writing, but few have done it so well. His style is one important reason why his stories are still read and loved today.', '说明·海明威的简洁文风', 156, '[{"q":"What does Hemingway compare good writing to?","answer":"B","options":["A loud and busy song.","An iceberg in the sea.","A very long letter.","A crowded market."],"explanation":"原文 ''good writing is like an iceberg'' 的转述。"},{"q":"How does Hemingway help readers feel emotion?","answer":"C","options":["By explaining every feeling directly.","By using very long sentences.","By describing simple actions and details.","By avoiding any description at all."],"explanation":"原文 ''describes simple actions… lets the reader feel the emotion'' 的转述。"},{"q":"Why does every word matter in his stories?","answer":"D","options":["Because the words are unusually long.","Because readers skip most of them.","Because he repeats every idea twice.","Because so much meaning is left unsaid."],"explanation":"原文 ''so much is left unsaid, every single word matters'' 的转述。"}]'::jsonb, '[{"word":"iceberg","cn":"冰山"},{"word":"plain","cn":"朴素的"},{"word":"imagination","cn":"想象力"}]'::jsonb, 2, 'elective4', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Lake Poets and Wordsworth', 'The Lake Poets were a group of English poets who lived in the beautiful Lake District in the early nineteenth century. The three best-known of them were William Wordsworth, Samuel Taylor Coleridge and Robert Southey. They are seen as an important part of the Romantic movement, which valued nature, feeling and simple country life. Wordsworth, who later became Britain''s Poet Laureate, often wrote about the natural world around him. In his short poem Written in March, he paints a fresh picture of an early spring day. Birds sing, a stream flows, cattle graze quietly, and snow melts away on the hills. Blue sky begins to prevail, and there is joy in the mountains and life in the fountains. The poem feels bright and full of hope. Through such simple scenes, Wordsworth invites readers to slow down and notice the quiet beauty of the world, and that is one reason his work is still loved today.', '文化·湖畔派诗人与《写于三月》', 155, '[{"q":"Where did the Lake Poets live?","answer":"A","options":["In England''s Lake District.","In the centre of London.","By the sea in France.","In a large industrial city."],"explanation":"原文 ''lived in the beautiful Lake District'' 的转述。"},{"q":"What did the Romantic movement value?","answer":"B","options":["Money and busy city life.","Nature, feeling and country life.","War, power and conquest.","Machines and modern science."],"explanation":"原文 ''valued nature, feeling and simple country life'' 的转述。"},{"q":"What kind of day does Written in March describe?","answer":"C","options":["A cold and lonely winter night.","A hot and tiring summer afternoon.","A bright early spring day full of hope.","A grey and rainy autumn day."],"explanation":"原文 ''a fresh picture of an early spring day… bright and full of hope'' 的转述。"}]'::jsonb, '[{"word":"stream","cn":"小溪"},{"word":"prevail","cn":"盛行"},{"word":"Poet Laureate","cn":"桂冠诗人"}]'::jsonb, 2, 'elective4', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'All the World''s a Stage', 'William Shakespeare, often called The Bard, is widely seen as the greatest playwright and poet in the English language. He wrote more than thirty plays and over a hundred and fifty sonnets, and he helped shape the very English we use today. One of his most famous passages comes from the comedy As You Like It. In it, a thoughtful character says that all the world is a stage, and all the men and women are merely players. He then compares a person''s life to a play in seven acts, from a crying baby in its nurse''s arms to a helpless old man at the very end. With humour and gentle sadness, Shakespeare reminds us that everyone plays many different parts during a lifetime. Though these lines were written more than four hundred years ago, they still feel true. That is why people around the world continue to read, perform and quote Shakespeare''s words after so many years.', '文学·莎士比亚与人生七阶', 158, '[{"q":"What is Shakespeare best known as?","answer":"D","options":["A famous modern scientist.","A powerful king of England.","A writer of children''s songs.","The greatest playwright in English."],"explanation":"原文 ''the greatest playwright and poet in the English language'' 的转述。"},{"q":"What does the speaker compare human life to?","answer":"A","options":["A play that has seven acts.","A long and difficult journey.","A quiet river in spring.","A single endless day."],"explanation":"原文 ''compares a person''s life to a play in seven acts'' 的转述。"},{"q":"Why are Shakespeare''s words still read today?","answer":"B","options":["They are short and very easy.","They still feel true after centuries.","They were written in Chinese.","They describe modern machines."],"explanation":"原文 ''written more than four hundred years ago, they still feel true'' 的转述。"}]'::jsonb, '[{"word":"playwright","cn":"剧作家"},{"word":"sonnet","cn":"十四行诗"},{"word":"quote","cn":"引用"}]'::jsonb, 2, 'elective4', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Su Shi and the Mid-Autumn Moon', 'Su Shi, also known as Su Dongpo, was one of China''s greatest poets. He lived during the Song dynasty and was also a painter, calligrapher and government official. He is remembered for freeing Chinese poetry from many old rules and for starting a bold, free style of writing. One of his best-loved works is the ci poem Shui Diao Ge Tou, written on a Mid-Autumn night while he was thinking of his younger brother far away. In the poem he looks up at the bright moon and asks the deep blue sky how old it is. He dreams of flying to the palaces in the sky, yet decides he is happier in the human world below. At the end, he sends a warm wish to those he loves, that they may enjoy long life and share the same beautiful moonlight, however far apart they are. This gentle and hopeful poem is still recited by Chinese people every Mid-Autumn Festival.', '文学·苏轼《水调歌头》', 159, '[{"q":"Besides writing poetry, what else was Su Shi skilled in?","answer":"C","options":["Sailing and fishing.","Building large bridges.","Painting, calligraphy and government work.","Playing football."],"explanation":"原文 ''a painter, calligrapher and government official'' 的转述。"},{"q":"When did Su Shi write Shui Diao Ge Tou?","answer":"D","options":["During a busy market day.","On a cold winter morning at sea.","While travelling in a foreign land.","On a Mid-Autumn night, missing his brother."],"explanation":"原文 ''on a Mid-Autumn night while he was thinking of his younger brother'' 的转述。"},{"q":"What does Su Shi wish for the people he loves at the end?","answer":"A","options":["Long life and shared moonlight, even when apart.","Great wealth and royal power.","A quick return to the capital.","An end to all writing of poems."],"explanation":"原文 ''enjoy long life and share the same beautiful moonlight'' 的转述。"}]'::jsonb, '[{"word":"calligrapher","cn":"书法家"},{"word":"ci poem","cn":"词"},{"word":"moonlight","cn":"月光"}]'::jsonb, 2, 'elective4', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Why Poetry Matters', 'Why does poetry matter in a world that seems to care most about money and success? In the film Dead Poets Society, a teacher named Mr Keating gives his students a surprising answer. Medicine, law and business, he says, are needed to keep us alive, but poetry, beauty and love are the very things we stay alive for. He reminds his class that the human race is full of strong feeling, and that each of us may add our own verse to the great play of life. The thinker Bertrand Russell once offered similar advice to future generations: always look honestly for the facts, and let love guide the way we treat one another. Both men believed that great writing helps us understand who we are and why we live. Reading classics, then, is far from a waste of time. It feeds the heart as well as the mind, and it can quietly change the way we see the whole world.', '议论·诗歌为何重要', 161, '[{"q":"According to Mr Keating, what do we stay alive for?","answer":"B","options":["Only money and success.","Poetry, beauty and love.","Sleep, food and comfort.","Fame and great power."],"explanation":"原文 ''poetry, beauty and love are the very things we stay alive for'' 的转述。"},{"q":"What advice did Bertrand Russell give future generations?","answer":"C","options":["Avoid reading any old books.","Care only about yourself.","Seek the truth and let love guide us.","Forget the whole past."],"explanation":"原文 ''look honestly for the facts, and let love guide…'' 的转述。"},{"q":"What is the writer''s main point about reading classics?","answer":"D","options":["It is mostly a waste of time.","It is only useful for exams.","It should be avoided by the young.","It feeds both the heart and the mind."],"explanation":"末段 ''feeds the heart as well as the mind'' 的转述。"}]'::jsonb, '[{"word":"matter","cn":"要紧;重要"},{"word":"verse","cn":"诗句"},{"word":"generation","cn":"一代人"}]'::jsonb, 2, 'elective4', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Recommending a Chinese Classic', 'My favourite Chinese (1)____ is Journey to the West, a story that almost everyone in China knows. It was (2)____ more than four hundred years ago and is still loved today. The book (3)____ the adventures of a monk and his three followers as they travel west to find holy books. The most famous (4)____ is the Monkey King, who is brave, clever and full of energy. Each chapter is an exciting (5)____ full of magic and danger. Behind the fun, however, the novel also teaches us about courage, friendship and never giving (6)____. I first read it when I was young, and I still (7)____ rereading it every year. The language is not too (8)____, so it is a good classic for beginners. If you want to (9)____ Chinese culture, this is a wonderful place to start. I highly (10)____ it to anyone who loves a good story.', 149, 2, '[{"q":"1","answer":"A","options":["classic","machine","market","price"],"explanation":"favourite classic 最爱的经典(作品)。"},{"q":"2","answer":"B","options":["eaten","written","sold","thrown"],"explanation":"was written 被写成。"},{"q":"3","answer":"C","options":["sells","buys","tells","hides"],"explanation":"tells the adventures 讲述冒险。"},{"q":"4","answer":"D","options":["weather","price","noise","character"],"explanation":"the most famous character 最著名的角色。"},{"q":"5","answer":"A","options":["adventure","mistake","machine","price"],"explanation":"an exciting adventure 一场精彩的冒险。"},{"q":"6","answer":"B","options":["off","up","in","out"],"explanation":"give up 放弃。"},{"q":"7","answer":"C","options":["forget","refuse","enjoy","lose"],"explanation":"enjoy rereading 喜欢重读。"},{"q":"8","answer":"D","options":["empty","late","rich","difficult"],"explanation":"not too difficult 不太难。"},{"q":"9","answer":"A","options":["appreciate","forget","waste","lose"],"explanation":"appreciate Chinese culture 欣赏中国文化。"},{"q":"10","answer":"B","options":["sell","recommend","throw","hide"],"explanation":"highly recommend 极力推荐。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Why We Should Read Classics', 'Some students think that old (1)____ are boring and out of date, but classics still have a lot to (2)____ us. A classic is a book that has been loved by readers for many (3)____. It deals with feelings and questions that never really (4)____, such as love, courage and the meaning of life. When you read a great novel, you can (5)____ the world through another person''s eyes. This makes both your heart and your mind (6)____. Classics can also improve your language, because they are often beautifully (7)____. Of course, some classics are not (8)____ to read, and you may need to go slowly. But the (9)____ is always worth it. Little by little, you will come to (10)____ why these books have lasted so long.', 128, 2, '[{"q":"1","answer":"C","options":["prices","noises","books","machines"],"explanation":"old books 旧书。"},{"q":"2","answer":"D","options":["sell","lose","throw","teach"],"explanation":"teach us 教给我们。"},{"q":"3","answer":"A","options":["years","minutes","metres","seconds"],"explanation":"for many years 许多年。"},{"q":"4","answer":"B","options":["cook","change","drive","swim"],"explanation":"never really change 从不真正改变。"},{"q":"5","answer":"C","options":["sell","hide","see","lose"],"explanation":"see the world 看世界。"},{"q":"6","answer":"D","options":["fall","sell","lose","grow"],"explanation":"makes your heart and mind grow 让心智成长。"},{"q":"7","answer":"A","options":["written","eaten","sold","driven"],"explanation":"beautifully written 写得优美。"},{"q":"8","answer":"B","options":["empty","easy","late","rich"],"explanation":"not easy to read 不易读。"},{"q":"9","answer":"C","options":["price","noise","effort","weather"],"explanation":"the effort is worth it 努力值得。"},{"q":"10","answer":"D","options":["forget","waste","sell","understand"],"explanation":"come to understand 渐渐明白。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'My First Long Classic', 'When my teacher asked us to read War and Peace, I was a little (1)____ because the book was so thick. On the first (2)____, I could only manage a few pages, and the long Russian names (3)____ me. I almost wanted to give (4)____. But my mother told me to read just twenty minutes every (5)____, and slowly things got easier. After a while, the characters began to feel like real (6)____. I started to (7)____ forward to my quiet reading time each night. By the end of the term, I had (8)____ the whole novel, and I felt very (9)____ of myself. That experience taught me that even the longest classic can be finished if you are (10)____.', 120, 2, '[{"q":"1","answer":"A","options":["worried","happy","rich","late"],"explanation":"a little worried 有点担心。"},{"q":"2","answer":"B","options":["price","day","noise","metre"],"explanation":"on the first day 第一天。"},{"q":"3","answer":"C","options":["helped","fed","confused","washed"],"explanation":"the names confused me 名字把我弄糊涂。"},{"q":"4","answer":"D","options":["off","in","out","up"],"explanation":"give up 放弃。"},{"q":"5","answer":"A","options":["day","year","century","never"],"explanation":"every day 每天。"},{"q":"6","answer":"B","options":["prices","people","noises","machines"],"explanation":"feel like real people 像真人。"},{"q":"7","answer":"C","options":["sell","hide","look","lose"],"explanation":"look forward to 期待。"},{"q":"8","answer":"D","options":["lost","sold","broken","finished"],"explanation":"had finished the novel 读完小说。"},{"q":"9","answer":"A","options":["proud","afraid","bored","sorry"],"explanation":"proud of myself 为自己自豪。"},{"q":"10","answer":"B","options":["lazy","patient","angry","late"],"explanation":"if you are patient 只要有耐心。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'World Reading Day at School', 'Every year on the twenty-third of April, our school (1)____ World Reading Day. It is one of my favourite (2)____ of the whole year. In the morning, each class (3)____ a few classic books to share with the others. Students stand up and (4)____ why they love a certain story. Some read a short (5)____ aloud, while others act out a famous (6)____ from a play. The library is open all day, and the teachers (7)____ us to borrow as many books as we like. There is even a (8)____ for the best book review. The day always reminds me how much (9)____ a good book can bring. By the time it (10)____, everyone leaves with a new story to read.', 121, 2, '[{"q":"1","answer":"C","options":["sells","forgets","celebrates","loses"],"explanation":"celebrates Reading Day 庆祝读书日。"},{"q":"2","answer":"D","options":["prices","noises","metres","days"],"explanation":"favourite days 最爱的日子。"},{"q":"3","answer":"A","options":["chooses","sells","hides","breaks"],"explanation":"each class chooses 每个班选。"},{"q":"4","answer":"B","options":["sell","explain","hide","lose"],"explanation":"explain why 解释原因。"},{"q":"5","answer":"C","options":["price","noise","poem","machine"],"explanation":"read a short poem 读一首短诗。"},{"q":"6","answer":"D","options":["price","noise","weather","scene"],"explanation":"a famous scene 著名的场景。"},{"q":"7","answer":"A","options":["encourage","stop","forbid","refuse"],"explanation":"encourage us to borrow 鼓励借书。"},{"q":"8","answer":"B","options":["noise","prize","price","metre"],"explanation":"a prize for the best review 最佳书评奖。"},{"q":"9","answer":"C","options":["price","noise","joy","weather"],"explanation":"how much joy 多少欢乐。"},{"q":"10","answer":"D","options":["sells","cooks","swims","ends"],"explanation":"by the time it ends 等到结束时。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'My Favourite Library', 'My favourite place in the whole town is the old public (1)____ near my home. It is quiet, warm and full of thousands of (2)____. Whenever I feel tired or sad, I go there to (3)____ among the shelves. I can spend a whole afternoon reading without (4)____ the time. The staff are always (5)____ and ready to help me find what I need. Last month they (6)____ me an old copy of a classic poem collection. Reading in such a peaceful (7)____ makes me feel calm and happy. It also (8)____ me to the many writers of the past, whose words still speak to us today. I really hope this wonderful library will stay (9)____ for many more years, so that other readers can (10)____ it as much as I do.', 132, 2, '[{"q":"1","answer":"A","options":["library","market","garden","machine"],"explanation":"public library 公共图书馆。"},{"q":"2","answer":"B","options":["prices","books","noises","metres"],"explanation":"thousands of books 数千本书。"},{"q":"3","answer":"C","options":["cook","drive","read","swim"],"explanation":"go there to read 去那里读书。"},{"q":"4","answer":"D","options":["selling","cooking","washing","noticing"],"explanation":"without noticing the time 不知不觉。"},{"q":"5","answer":"A","options":["kind","rude","lazy","angry"],"explanation":"the staff are kind 工作人员友善。"},{"q":"6","answer":"B","options":["threw","found","washed","drove"],"explanation":"found me an old copy 帮我找到旧本。"},{"q":"7","answer":"C","options":["price","noise","place","metre"],"explanation":"a peaceful place 宁静的地方。"},{"q":"8","answer":"D","options":["sells","breaks","loses","connects"],"explanation":"connects me to the past 把我与过去相连。"},{"q":"9","answer":"A","options":["open","empty","late","rich"],"explanation":"stay open 继续开放。"},{"q":"10","answer":"B","options":["forget","enjoy","waste","lose"],"explanation":"enjoy it 享受它。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'How to Continue a Story', 'Writing the continuation of a story can be great (1)____ if you know a few simple tricks. First, read the given part of the story (2)____, and underline the most important details. Think carefully about who the main (3)____ are and what problem they face. A good continuation should follow the same (4)____ and keep the characters acting in a believable (5)____. Every new event must move the (6)____ forward, and the ending should feel natural rather than (7)____. Try to show the characters'' feelings through their actions instead of just (8)____ them. Before you finish, read your work again and (9)____ any small mistakes. With a little practice, you will be able to (10)____ stories that your readers really enjoy.', 121, 2, '[{"q":"1","answer":"C","options":["price","noise","fun","metre"],"explanation":"great fun 很有趣。"},{"q":"2","answer":"D","options":["loudly","angrily","sadly","carefully"],"explanation":"read carefully 仔细读。"},{"q":"3","answer":"A","options":["characters","prices","noises","metres"],"explanation":"the main characters 主要人物。"},{"q":"4","answer":"B","options":["price","style","noise","weather"],"explanation":"the same style 相同的风格。"},{"q":"5","answer":"C","options":["price","noise","way","metre"],"explanation":"in a believable way 以可信的方式。"},{"q":"6","answer":"D","options":["price","noise","weather","story"],"explanation":"move the story forward 推动故事发展。"},{"q":"7","answer":"A","options":["strange","rich","late","empty"],"explanation":"natural rather than strange 自然而不突兀。"},{"q":"8","answer":"B","options":["selling","telling","cooking","driving"],"explanation":"instead of just telling 而非只是直说。"},{"q":"9","answer":"C","options":["sell","hide","correct","lose"],"explanation":"correct any mistakes 改正错误。"},{"q":"10","answer":"D","options":["sell","cook","drive","write"],"explanation":"able to write stories 能写出故事。"}]'::jsonb, 6, 'sufe');
